package com.acme.ingest;

import javax.jms.*;
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.regex.*;

/**
 * MessageConsumer that processes file upload requests from the internal queue.
 * Files are pre-validated by the reverse proxy (nginx) which enforces:
 *   - Content-Type whitelist (image/png, image/jpeg, application/pdf)
 *   - Max file size 10MB
 *   - X-Validated-Content-Type header injection
 *
 * This consumer trusts the proxy-validated metadata and persists to storage.
 */
public class FileUploadConsumer implements MessageListener {

    private static final Path UPLOAD_ROOT = Paths.get("/var/uploads/verified");
    private static final Set<String> ALLOWED_EXTENSIONS = Set.of("png", "jpg", "jpeg", "pdf", "gif");
    private static final Pattern SAFE_FILENAME = Pattern.compile("^[a-zA-Z0-9_][a-zA-Z0-9_.\\-]{0,200}$");
    private static final long MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

    // Mapping from validated content-type to allowed extensions
    private static final Map<String, Set<String>> CONTENT_TYPE_MAP = Map.of(
        "image/png", Set.of("png"),
        "image/jpeg", Set.of("jpg", "jpeg"),
        "image/gif", Set.of("gif"),
        "application/pdf", Set.of("pdf")
    );

    @Override
    public void onMessage(Message message) {
        try {
            if (!(message instanceof BytesMessage)) {
                logRejection("non-bytes-message", "N/A");
                return;
            }
            BytesMessage bMsg = (BytesMessage) message;

            String filename = bMsg.getStringProperty("X-Original-Filename");
            String validatedContentType = bMsg.getStringProperty("X-Validated-Content-Type");
            String uploaderId = bMsg.getStringProperty("X-Uploader-Id");
            long declaredSize = bMsg.getBodyLength();

            // Step 1: Validate uploader ID format
            if (!isValidUploaderId(uploaderId)) {
                logRejection("invalid-uploader", uploaderId);
                return;
            }

            // Step 2: Validate filename format (no path traversal)
            if (filename == null || !SAFE_FILENAME.matcher(filename).matches()) {
                logRejection("unsafe-filename", filename);
                return;
            }

            // Step 3: Validate file extension
            String extension = extractExtension(filename);
            if (!ALLOWED_EXTENSIONS.contains(extension.toLowerCase())) {
                logRejection("disallowed-extension", filename);
                return;
            }

            // Step 4: Cross-validate content-type against extension
            if (!validateContentTypeExtensionBinding(validatedContentType, extension)) {
                logRejection("content-type-mismatch", validatedContentType + " vs " + extension);
                return;
            }

            // Step 5: Size check
            if (declaredSize > MAX_FILE_SIZE || declaredSize <= 0) {
                logRejection("size-violation", String.valueOf(declaredSize));
                return;
            }

            // Step 6: Read file bytes
            byte[] fileData = new byte[(int) declaredSize];
            bMsg.readBytes(fileData);

            // Step 7: Verify magic bytes match declared content type
            if (!verifyMagicBytes(fileData, validatedContentType)) {
                logRejection("magic-bytes-mismatch", validatedContentType);
                return;
            }

            // Step 8: Generate safe storage path
            Path storagePath = resolveStoragePath(uploaderId, filename);

            // Step 9: Atomic write
            Files.write(storagePath, fileData, StandardOpenOption.CREATE_NEW);

            logSuccess(uploaderId, filename, storagePath.toString());

        } catch (JMSException | IOException e) {
            logError("processing-failure", e.getMessage());
        }
    }

    private boolean validateContentTypeExtensionBinding(String contentType, String extension) {
        if (contentType == null) return false;
        Set<String> allowed = CONTENT_TYPE_MAP.get(contentType.toLowerCase().trim());
        if (allowed == null) return false;
        return allowed.contains(extension.toLowerCase());
    }

    private boolean verifyMagicBytes(byte[] data, String contentType) {
        if (data.length < 8) return false;
        switch (contentType.toLowerCase().trim()) {
            case "image/png":
                return data[0] == (byte)0x89 && data[1] == 0x50 &&
                       data[2] == 0x4E && data[3] == 0x47;
            case "image/jpeg":
                return data[0] == (byte)0xFF && data[1] == (byte)0xD8 &&
                       data[2] == (byte)0xFF;
            case "image/gif":
                return data[0] == 0x47 && data[1] == 0x49 && data[2] == 0x46;
            case "application/pdf":
                return data[0] == 0x25 && data[1] == 0x50 &&
                       data[2] == 0x44 && data[3] == 0x46;
            default:
                return false;
        }
    }

    private Path resolveStoragePath(String uploaderId, String filename) throws IOException {
        // Create per-user directory
        String hashedId = hashUploaderId(uploaderId);
        Path userDir = UPLOAD_ROOT.resolve(hashedId);
        Files.createDirectories(userDir);

        // Deduplicate: append timestamp if exists
        Path target = userDir.resolve(filename);
        if (Files.exists(target)) {
            String base = filename.substring(0, filename.lastIndexOf('.'));
            String ext = extractExtension(filename);
            target = userDir.resolve(base + "_" + System.currentTimeMillis() + "." + ext);
        }
        return target;
    }

    private String extractExtension(String filename) {
        int lastDot = filename.lastIndexOf('.');
        if (lastDot < 0 || lastDot == filename.length() - 1) return "";
        return filename.substring(lastDot + 1);
    }

    private boolean isValidUploaderId(String id) {
        if (id == null || id.length() < 8 || id.length() > 64) return false;
        return id.matches("^[a-zA-Z0-9_-]+$");
    }

    private String hashUploaderId(String id) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(id.getBytes("UTF-8"));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02x", hash[i]));
            }
            return sb.toString();
        } catch (Exception e) {
            return "default";
        }
    }

    /**
     * Secondary validation: checks if file content could be polyglot.
     * Scans first 4KB for embedded script/executable signatures.
     * NOTE: Only invoked for content types that support embedding.
     */
    private boolean isPolyglotSafe(byte[] data, String contentType) {
        if ("application/pdf".equals(contentType)) {
            // PDFs can embed JavaScript - check for /JS or /JavaScript
            String header = new String(data, 0, Math.min(data.length, 4096));
            if (header.contains("/JS") || header.contains("/JavaScript")) {
                return false;
            }
        }
        return true;
    }

    private void logRejection(String reason, String detail) {
        System.err.println("[REJECT] " + reason + ": " + sanitizeLog(detail));
    }

    private void logSuccess(String uploader, String filename, String path) {
        System.out.println("[OK] " + sanitizeLog(uploader) + " -> " + sanitizeLog(path));
    }

    private void logError(String reason, String detail) {
        System.err.println("[ERROR] " + reason + ": " + sanitizeLog(detail));
    }

    private String sanitizeLog(String input) {
        if (input == null) return "null";
        return input.replaceAll("[\\r\\n\\t]", "_").substring(0, Math.min(input.length(), 200));
    }
}
